140	/* --------------------------------------------------------
141	 * Fetch / decode / dispatch loop
142	 *
143	 * Currently handles NOP and HALT. Additional opcodes are
144	 * added in separate modules (vm_ctrl.plsw, vm_data.plsw,
145	 * etc.) as the VM grows.
146	 * -------------------------------------------------------- */
147	
148	VM_RUN: PROC;
149	    DCL PC INT;
150	    DCL IMM INT;
151	    DCL REGVAL INT;
152	
153	    G_RUNNING = 1;
154	
155	    DO WHILE (G_RUNNING = 1);
156	        PC = REG_GET(REG_PC);
157	        G_INST = MEM(PC);
158	        ?INST_DECODE(SRC(ADDR(G_INST)));
159	        CALL VM_TRACE(PC, G_OP);
160	
161	        SELECT;
162	            WHEN (G_OP = OP_NOP) DO;
163	                CALL REG_SET(REG_PC, PC + 1);
164	            END;
165	
166	            WHEN (G_OP = OP_HALT) DO;
167	                CALL UART_PUTS(ADDR(M_HALT));
168	                G_RUNNING = 0;
169	            END;
170	
171	            /* PUT_CONST Ai, [imm] -- 2-cell
172	             * Load tagged constant from next cell into Ai */
173	            WHEN (G_OP = OP_PUT_CONST) DO;
174	                IMM = MEM(PC + 1);
175	                CALL REG_SET(G_OP1, IMM);
176	                CALL REG_SET(REG_PC, PC + 2);
177	            END;
178	
179	            /* GET_CONST Ai, [imm] -- 2-cell
180	             * Unify Ai with tagged constant from next cell.
181	             * Initial version: direct equality check only.
182	             * Full unification with REF dereferencing is a
183	             * later step. */
184	            WHEN (G_OP = OP_GET_CONST) DO;
185	                IMM = MEM(PC + 1);
186	                REGVAL = REG_GET(G_OP1);
187	                IF (REGVAL = IMM) THEN DO;
188	                    CALL REG_SET(REG_PC, PC + 2);
189	                END;
190	                ELSE DO;
191	                    CALL UART_PUTS(ADDR(M_FAIL));
192	                    G_RUNNING = 0;
193	                END;
194	            END;
195	
196	            /* CALL [imm] -- 2-cell
197	             * Save return address (PC+2) in CP, jump to
198	             * target address in next cell */
199	            WHEN (G_OP = OP_CALL) DO;
200	                CALL REG_SET(REG_CP, PC + 2);
201	                IMM = MEM(PC + 1);
202	                CALL REG_SET(REG_PC, IMM);
203	            END;
204	
205	            /* PROCEED -- 1-cell
206	             * Return to continuation: set PC = CP */
207	            WHEN (G_OP = OP_PROCEED) DO;
208	                CALL REG_SET(REG_PC, REG_GET(REG_CP));
209	            END;
210	
211	            /* FAIL -- 1-cell
212	             * Force backtracking. No choice points yet,
213	             * so just halt with failure. */
214	            WHEN (G_OP = OP_FAIL) DO;
215	                CALL UART_PUTS(ADDR(M_FAIL));
216	                G_RUNNING = 0;
217	            END;
