171	END;
172	
173	CP_WRITE: PROC(BASE INT, OFF INT, VAL INT);
174	    MEM(BASE + OFF) = VAL;
175	END;
176	
177	/* Save a full choice-point frame.
178	 * ALT is the code address of the next alternative clause.
179	 *
180	 * Convention: BP points to the base of the most recent frame.
181	 * New frame is written at the top of the choice-point stack
182	 * (BP + CP_FRAME_SIZE if a frame exists, or CP_BASE if first).
183	 * For simplicity, we use BP as the write position and then
184	 * advance: the initial BP = CP_BASE serves as a sentinel
185	 * (prev_BP = CP_BASE means "no previous frame"). */
186	CP_PUSH: PROC(ALT INT);
187	    DCL OLD_BP INT;
188	    DCL NEW_BP INT;
189	    OLD_BP = REG_GET(REG_BP);
190	    NEW_BP = OLD_BP;
191	    IF (OLD_BP != CP_BASE) THEN
192	        NEW_BP = OLD_BP + CP_FRAME_SIZE;
193	    IF (NEW_BP + CP_FRAME_SIZE > CP_BASE + CP_STKSZ) THEN DO;
194	        CALL UART_PUTS(ADDR(M_CPOV));
195	        G_RUNNING = 0;
196	        RETURN;
197	    END;
198	    CALL CP_WRITE(NEW_BP, CPF_PREV_BP,  OLD_BP);
199	    CALL CP_WRITE(NEW_BP, CPF_SAVED_CP, REG_GET(REG_CP));
200	    CALL CP_WRITE(NEW_BP, CPF_SAVED_EP, REG_GET(REG_EP));
201	    CALL CP_WRITE(NEW_BP, CPF_SAVED_HP, REG_GET(REG_HP));
202	    CALL CP_WRITE(NEW_BP, CPF_SAVED_TR, REG_GET(REG_TR));
203	    CALL CP_WRITE(NEW_BP, CPF_NEXT_ALT, ALT);
204	    CALL CP_WRITE(NEW_BP, CPF_SAVED_A0, REG_GET(REG_A0));
205	    CALL CP_WRITE(NEW_BP, CPF_SAVED_A1, REG_GET(REG_A1));
206	    CALL CP_WRITE(NEW_BP, CPF_SAVED_A2, REG_GET(REG_A2));
207	    CALL CP_WRITE(NEW_BP, CPF_SAVED_A3, REG_GET(REG_A3));
208	    CALL CP_WRITE(NEW_BP, CPF_SAVED_A4, REG_GET(REG_A4));
209	    CALL CP_WRITE(NEW_BP, CPF_SAVED_A5, REG_GET(REG_A5));
210	    CALL CP_WRITE(NEW_BP, CPF_SAVED_A6, REG_GET(REG_A6));
211	    CALL CP_WRITE(NEW_BP, CPF_SAVED_A7, REG_GET(REG_A7));
212	    CALL REG_SET(REG_BP, NEW_BP);
213	END;
214	
215	/* Restore state from the most recent choice-point frame.
216	 * Unwinds trail, resets HP, restores A0-A7 and CP/EP.
217	 * Pops the frame by setting BP = prev_BP.
218	 * Returns the next_alt address so the caller can jump there. */
219	/* Restore state from the current choice-point frame WITHOUT
220	 * popping it. Used by FAIL to jump to the alternative.
221	 * Unwinds trail, resets HP, restores A0-A7 and CP/EP.
222	 * Returns the next_alt address. BP is unchanged. */
223	CP_RESTORE: PROC RETURNS(INT);
224	    DCL FB INT;
225	    DCL SAVED_TR INT;
226	    DCL SAVED_HP INT;
227	    FB = REG_GET(REG_BP);
228	
229	    /* Unwind trail and reset heap */
230	    SAVED_TR = CP_READ(FB, CPF_SAVED_TR);
231	    SAVED_HP = CP_READ(FB, CPF_SAVED_HP);
232	    CALL TRAIL_UNWIND(SAVED_TR);
233	    CALL REG_SET(REG_HP, SAVED_HP);
234	
235	    /* Restore registers */
236	    CALL REG_SET(REG_CP, CP_READ(FB, CPF_SAVED_CP));
237	    CALL REG_SET(REG_EP, CP_READ(FB, CPF_SAVED_EP));
238	    CALL REG_SET(REG_A0, CP_READ(FB, CPF_SAVED_A0));
239	    CALL REG_SET(REG_A1, CP_READ(FB, CPF_SAVED_A1));
240	    CALL REG_SET(REG_A2, CP_READ(FB, CPF_SAVED_A2));
241	    CALL REG_SET(REG_A3, CP_READ(FB, CPF_SAVED_A3));
242	    CALL REG_SET(REG_A4, CP_READ(FB, CPF_SAVED_A4));
243	    CALL REG_SET(REG_A5, CP_READ(FB, CPF_SAVED_A5));
244	    CALL REG_SET(REG_A6, CP_READ(FB, CPF_SAVED_A6));
245	    CALL REG_SET(REG_A7, CP_READ(FB, CPF_SAVED_A7));
246	
247	    RETURN(CP_READ(FB, CPF_NEXT_ALT));
248	END;
249	
250	/* Restore state AND pop the choice-point frame.
251	 * Used by TRUST (last alternative). */
252	CP_POP: PROC RETURNS(INT);
253	    DCL ALT INT;
254	    ALT = CP_RESTORE;
255	    CALL REG_SET(REG_BP, CP_READ(REG_GET(REG_BP), CPF_PREV_BP));
256	    RETURN(ALT);
257	END;
258	
259	/* --------------------------------------------------------
260	 * Atom table
261	 * -------------------------------------------------------- */
262	
263	/* Store a string into atom table slot ID.
264	 * STR_ADDR is the address of a null-terminated CHAR array.
265	 * Copies up to ATOM_SLOT_SIZE-1 chars, null-terminates. */
266	ATOM_STORE: PROC(ID INT, C0 INT, C1 INT, C2 INT, C3 INT,
267	                  C4 INT, C5 INT, C6 INT);
268	    DCL BASE INT;
269	    BASE = ATOM_BASE + ID * ATOM_SLOT_SIZE;
270	    MEM(BASE)     = C0;
271	    MEM(BASE + 1) = C1;
272	    MEM(BASE + 2) = C2;
273	    MEM(BASE + 3) = C3;
274	    MEM(BASE + 4) = C4;
275	    MEM(BASE + 5) = C5;
276	    MEM(BASE + 6) = C6;
277	    MEM(BASE + 7) = 0;
278	END;
279	
280	/* Initialize the atom table with known atoms. */
281	ATOM_INIT: PROC;
282	    /* 0: []       */  CALL ATOM_STORE(0, 91, 93, 0, 0, 0, 0, 0);
283	    /* 1: bob      */  CALL ATOM_STORE(1, 98, 111, 98, 0, 0, 0, 0);
284	    /* 2: ann      */  CALL ATOM_STORE(2, 97, 110, 110, 0, 0, 0, 0);
285	    /* 3: joe      */  CALL ATOM_STORE(3, 106, 111, 101, 0, 0, 0, 0);
286	    /* 4: liz      */  CALL ATOM_STORE(4, 108, 105, 122, 0, 0, 0, 0);
287	    /* 5: parent   */  CALL ATOM_STORE(5, 112, 97, 114, 101, 110, 116, 0);
288	    /* 6: ancestor */  CALL ATOM_STORE(6, 97, 110, 99, 101, 115, 116, 111);
289	    /* Note: "ancestor" is 8 chars, truncated to 7 + null.
290	     * PLSW-ISSUE: ATOM_SLOT_SIZE of 8 is tight for longer names.
291	     * Could increase to 12 or use variable-length encoding later. */
292	END;
293	
294	/* Print an atom name by ID from the atom table. */
295	ATOM_PRINT: PROC(ID INT);
296	    DCL BASE INT;
297	    DCL I INT;
298	    DCL CH INT;
299	    BASE = ATOM_BASE + ID * ATOM_SLOT_SIZE;
300	    I = 0;
301	    CH = MEM(BASE);
302	    DO WHILE (CH != 0 AND I < ATOM_SLOT_SIZE);
303	        CALL UART_PUTCHAR(CH);
304	        I = I + 1;
305	        CH = MEM(BASE + I);
306	    END;
307	END;
308	
309	/* --------------------------------------------------------
310	 * VM initialization
311	 * -------------------------------------------------------- */
312	
313	VM_INIT: PROC;
314	    DCL I INT;
315	
316	    /* Zero all memory */
317	    DO I = 0 TO 7703;
318	        MEM(I) = 0;
319	    END;
320	
321	    /* Populate atom table */
322	    CALL ATOM_INIT;
323	
324	    /* Set initial register values */
325	    CALL REG_SET(REG_PC, CODE_BASE);
326	    CALL REG_SET(REG_HP, HEAP_BASE);
327	    CALL REG_SET(REG_TR, TRAIL_BASE);
328	    CALL REG_SET(REG_EP, ENV_BASE);
329	    CALL REG_SET(REG_BP, CP_BASE);
330	    CALL REG_SET(REG_MODE, 0);
331	END;
332	
