661	
662	LOAD_PUT_VAR_TEST: PROC;
663	    MEM(0) = OP_PUT_CONST * OP_MULT;                  /* PUT_CONST A0 */
664	    MEM(1) = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
665	    MEM(2) = OP_PUT_VAR * OP_MULT + REG_X0 * OP1_MULT + REG_A1; /* PUT_VAR X0, A1 */
666	    MEM(3) = OP_HALT * OP_MULT;                       /* HALT */
667	END;
