669	/* --------------------------------------------------------
670	 * Unification test: query parent(bob, X) against
671	 * clause parent(bob, ann). GET_CONST A1 should bind X
672	 * to atom(ann) via DEREF+BIND.
673	 *
674	 * Expected: A1 derefs to atom(ann) = 4194306 after PROCEED.
675	 * -------------------------------------------------------- */
676	
677	LOAD_UNIFY_TEST: PROC;
678	    /* Query: ?- parent(bob, X). */
679	    MEM(0)  = OP_PUT_CONST * OP_MULT;                  /* PUT_CONST A0 */
680	    MEM(1)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
681	    MEM(2)  = OP_PUT_VAR * OP_MULT + REG_X0 * OP1_MULT + REG_A1; /* PUT_VAR X0, A1 */
682	    MEM(3)  = OP_CALL * OP_MULT;                       /* CALL */
683	    MEM(4)  = 7;                                        /* target: addr 7 */
684	    MEM(5)  = OP_HALT * OP_MULT;                       /* HALT */
685	
686	    /* Clause: parent(bob, ann). at addr 7 */
687	    MEM(7)  = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
688	    MEM(8)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) -- match */
689	    MEM(9)  = OP_GET_CONST * OP_MULT + 1 * OP1_MULT;  /* GET_CONST A1 */
690	    MEM(10) = TAG_ATOM * TAG_MULT + 2;                 /* atom(ann) -- binds X */
691	    MEM(11) = OP_PROCEED * OP_MULT;                    /* PROCEED */
692	END;
693	
694	/* --------------------------------------------------------
695	 * TRY/TRUST test: two-clause predicate, query first clause.
696	 *
697	 * pred/1: clause1 = pred(bob).  clause2 = pred(ann).
698	 * Query: ?- pred(bob).  (matches clause1 via TRY path)
699	 *
700	 * Layout:
701	 *   0-1: PUT_CONST A0, bob
702	 *   2-3: CALL 6
703	 *   4:   HALT
704	 *   6-7: TRY 12        (alt = clause2 at addr 12)
705	 *   8-9: GET_CONST A0, bob   (clause1)
706	 *   10:  PROCEED
707	 *   12:  TRUST          (clause2 entry)
708	 *   13-14: GET_CONST A0, ann
709	 *   15:  PROCEED
710	 *
711	 * Expected: TRY pushes choice point, clause1 matches,
712	 * PROCEED returns to HALT. Choice point left on stack
713	 * (would be used by FAIL if query continued).
714	 * -------------------------------------------------------- */
715	
716	LOAD_TRY_TEST: PROC;
717	    /* Query */
718	    MEM(0)  = OP_PUT_CONST * OP_MULT;                  /* PUT_CONST A0 */
719	    MEM(1)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
720	    MEM(2)  = OP_CALL * OP_MULT;                       /* CALL */
721	    MEM(3)  = 6;                                        /* target: pred/1 */
722	    MEM(4)  = OP_HALT * OP_MULT;                       /* HALT */
723	
724	    /* pred/1 dispatch */
725	    MEM(6)  = OP_TRY * OP_MULT;                        /* TRY */
726	    MEM(7)  = 12;                                       /* alt: clause2 */
727	
728	    /* clause1: pred(bob). */
729	    MEM(8)  = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
730	    MEM(9)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
731	    MEM(10) = OP_PROCEED * OP_MULT;                    /* PROCEED */
732	
733	    /* clause2: pred(ann). */
734	    MEM(12) = OP_TRUST * OP_MULT;                      /* TRUST */
735	    MEM(13) = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
736	    MEM(14) = TAG_ATOM * TAG_MULT + 2;                 /* atom(ann) */
737	    MEM(15) = OP_PROCEED * OP_MULT;                    /* PROCEED */
738	END;
739	
740	/* --------------------------------------------------------
741	 * Backtracking test: query pred(ann) against pred(bob)/pred(ann).
742	 * Clause1 fails at GET_CONST (bob != ann), backtracks to
743	 * clause2 via TRUST, which matches. Should succeed.
744	 *
745	 * Same code layout as LOAD_TRY_TEST but query uses atom(ann).
746	 * -------------------------------------------------------- */
747	
748	LOAD_BACKTRACK_TEST: PROC;
749	    /* Query: ?- pred(ann). */
750	    MEM(0)  = OP_PUT_CONST * OP_MULT;                  /* PUT_CONST A0 */
751	    MEM(1)  = TAG_ATOM * TAG_MULT + 2;                 /* atom(ann) */
752	    MEM(2)  = OP_CALL * OP_MULT;                       /* CALL */
753	    MEM(3)  = 6;                                        /* target: pred/1 */
754	    MEM(4)  = OP_HALT * OP_MULT;                       /* HALT */
755	
756	    /* pred/1 dispatch */
757	    MEM(6)  = OP_TRY * OP_MULT;                        /* TRY */
758	    MEM(7)  = 12;                                       /* alt: clause2 */
759	
760	    /* clause1: pred(bob). -- will fail */
761	    MEM(8)  = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
762	    MEM(9)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
763	    MEM(10) = OP_PROCEED * OP_MULT;                    /* PROCEED */
764	
765	    /* clause2: pred(ann). -- will match */
766	    MEM(12) = OP_TRUST * OP_MULT;                      /* TRUST */
767	    MEM(13) = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
768	    MEM(14) = TAG_ATOM * TAG_MULT + 2;                 /* atom(ann) */
769	    MEM(15) = OP_PROCEED * OP_MULT;                    /* PROCEED */
770	END;
771	
772	/* --------------------------------------------------------
773	 * two_facts: parent(bob, ann). parent(bob, joe).
774	 *            ?- parent(bob, X), write(X), nl, fail.
775	 *
776	 * Atoms: 1=bob, 2=ann, 3=joe
