789	    MEM(1)  = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
790	    MEM(2)  = OP_PUT_VAR * OP_MULT + REG_X0 * OP1_MULT + REG_A1; /* PUT_VAR X0, A1 */
