798	    MEM(10) = OP_TRY * OP_MULT;                        /* TRY */
799	    MEM(11) = 19;                                       /* alt: clause2 at 0x13 */
800	
801	    /* Clause 1: parent(bob, ann). */
802	    MEM(12) = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
803	    MEM(13) = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
804	    MEM(14) = OP_GET_CONST * OP_MULT + REG_A1 * OP1_MULT; /* GET_CONST A1 */
805	    MEM(15) = TAG_ATOM * TAG_MULT + 2;                 /* atom(ann) */
806	    MEM(16) = OP_PROCEED * OP_MULT;                    /* PROCEED */
807	
808	    /* Clause 2: parent(bob, joe). at addr 19 (0x13) */
809	    MEM(19) = OP_TRUST * OP_MULT;                      /* TRUST */
810	    MEM(20) = OP_GET_CONST * OP_MULT;                  /* GET_CONST A0 */
811	    MEM(21) = TAG_ATOM * TAG_MULT + 1;                 /* atom(bob) */
812	    MEM(22) = OP_GET_CONST * OP_MULT + REG_A1 * OP1_MULT; /* GET_CONST A1 */
813	    MEM(23) = TAG_ATOM * TAG_MULT + 3;                 /* atom(joe) */
814	    MEM(24) = OP_PROCEED * OP_MULT;                    /* PROCEED */
815	END;
