        'la r2,255';
        'and r1,r1,r2';
        'la r2,G_OP1';
        'sw r1,0(r2)';
        /* op2 = bits 7-0 */
        'la r1,255';
        'and r0,r0,r1';
        'la r1,G_OP2';
        'sw r0,0(r1)';
    END;
END;

