 * Results written to globals G_OP, G_OP1, G_OP2.
 *
 *   ?INST_DECODE(SRC(ADDR(G_INST)));
 * -------------------------------------------------------- */

MACRODEF INST_DECODE;
    REQUIRED SRC(expr);
    GEN DO;
        'la r0,{SRC}';
        'lw r0,0(r0)';
        /* op2 = bits 7-0 (extract first, r0 still has full inst) */
        'mov r1,r0';
        'la r2,255';
        'and r1,r2';
        'la r2,_G_OP2';
        'sw r1,0(r2)';
