input.command:
# vm_heap.plsw has DCL M_HEAPOV and M_TRLOV at the bottom.
# It also calls REG_GET and REG_SET which are defined in vm_regs.plsw.
# The compiler might treat the CALL REG_GET as a variable reference.

# Let me try a minimal test: vm_heap without calling REG_GET/REG_SET
# Actually, the simplest fix: the compiler emits `la r2,_REG_GET; jal r1,(r2)`
# for CALL REG_GET -- if it treats REG_GET as undefined, that's the error.

# Let me test: does a CALL to an undefined PROC produce "undefined variable"?
cat > /tmp/test_undef.plsw <<'EOF'
%DEFINE LIBRARY;

TEST: PROC;
    CALL UNKNOWN_FUNC;
END;

MAIN: PROC;
END;
EOF

COMPILER_ASM="$HOME/github/sw-embed/sw-cor24-plsw/build/plsw.s"
cor24-run --run "$COMPILER_ASM" -u "$(printf 'c\nSOURCE:\n'; cat /tmp/test_undef.plsw; printf '\x04')" -n 200000000 -t 120 --speed 0 2>&1 | grep -E "ERROR|failed|compil" | head -5

