# Try declaring a PROC with no body (forward declaration)
cat > /tmp/test_fwd.plsw <<'EOF'
/* Forward declare */
HELPER: PROC(X INT) RETURNS(INT);
END;

MAIN: PROC;
    DCL V INT;
    V = HELPER(42);
    CALL UART_PUTCHAR(V + 48);
    CALL UART_PUTCHAR(10);
END;
EOF

COMPILER_ASM="$HOME/github/sw-embed/sw-cor24-plsw/build/plsw.s"
cor24-run --run "$COMPILER_ASM" -u "$(printf 'c\nSOURCE:\n'; cat /tmp/test_fwd.plsw; printf '\x04')" -n 200000000 -t 120 --speed 0 2>&1 | sed -n '/^UART output:/,/^Executed/{/^Executed/d;p;}' | sed '1s/^UART output: //' | tail -10

