105	             * Copy Y[op1] from environment frame to Ai. */
106	            WHEN (G_OP = OP_PUT_Y_VAL) DO;
107	                CALL REG_SET(G_OP2, Y_GET(G_OP1));
108	                CALL REG_SET(REG_PC, PC + 1);
109	            END;
