143	                        END;
144	                    END;
145	                END;
146	            END;
147	
148	            /* CALL [imm] -- 2-cell */
149	            WHEN (G_OP = OP_CALL) DO;
150	                CALL REG_SET(REG_CP, PC + 2);
151	                IMM = MEM(PC + 1);
152	                CALL REG_SET(REG_PC, IMM);
153	            END;
