155	            /* EXECUTE [imm] -- 2-cell (tail call, no CP save) */
156	            WHEN (G_OP = OP_EXECUTE) DO;
157	                IMM = MEM(PC + 1);
158	                CALL REG_SET(REG_PC, IMM);
159	            END;
