161	            /* PROCEED -- 1-cell */
162	            WHEN (G_OP = OP_PROCEED) DO;
163	                CALL REG_SET(REG_PC, REG_GET(REG_CP));
164	            END;
165	
166	            /* TRY [imm] -- 2-cell */
167	            WHEN (G_OP = OP_TRY) DO;
168	                IMM = MEM(PC + 1);
169	                CALL CP_PUSH(IMM);
170	                CALL REG_SET(REG_PC, PC + 2);
171	            END;
