173	            /* RETRY [imm] -- 2-cell
174	             * Middle alternative: restore from choice point,
175	             * update next_alt to [imm], fall through. */
176	            WHEN (G_OP = OP_RETRY) DO;
177	                DCL RT_DUMMY INT;
178	                DCL RT_FB INT;
179	                RT_DUMMY = CP_RESTORE();
180	                /* Update next_alt in the current frame */
181	                RT_FB = REG_GET(REG_BP) - CP_FRAME_SIZE;
182	                IMM = MEM(PC + 1);
