196	             * Sets BP = CP_BASE. A proper WAM CUT would
197	             * restore to the BP at predicate entry; this
198	             * simplified version is noted as a limitation. */
199	            WHEN (G_OP = OP_CUT) DO;
200	                CALL REG_SET(REG_BP, CP_BASE);
201	                CALL REG_SET(REG_PC, PC + 1);
202	            END;
