264	                    END;
265	                    OTHERWISE DO;
266	                        CALL PRINT_INT(WVAL);
267	                    END;
268	                END;
269	                CALL REG_SET(REG_PC, PC + 1);
270	            END;
271	
272	            /* B_NL -- 1-cell */
273	            WHEN (G_OP = OP_B_NL) DO;
274	                CALL UART_PUTCHAR(10);
275	                CALL REG_SET(REG_PC, PC + 1);
276	            END;
277	
278	            /* B_IS_ADD -- 1-cell
279	             * A0 = A1 + A2 (INT payloads). */
280	            WHEN (G_OP = OP_B_IS_ADD) DO;
281	                DCL ADD_L INT;
282	                DCL ADD_R INT;
283	                ADD_L = CELL_PAY(DEREF(REG_GET(REG_A1)));
284	                ADD_R = CELL_PAY(DEREF(REG_GET(REG_A2)));
285	                CALL REG_SET(REG_A0, MAKE_CELL(TAG_INT, ADD_L + ADD_R));
286	                CALL REG_SET(REG_PC, PC + 1);
287	            END;
288	
289	            /* B_IS_SUB -- 1-cell
290	             * A0 = A1 - A2 (INT payloads). */
291	            WHEN (G_OP = OP_B_IS_SUB) DO;
292	                DCL SUB_L INT;
293	                DCL SUB_R INT;
294	                SUB_L = CELL_PAY(DEREF(REG_GET(REG_A1)));
295	                SUB_R = CELL_PAY(DEREF(REG_GET(REG_A2)));
296	                CALL REG_SET(REG_A0, MAKE_CELL(TAG_INT, SUB_L - SUB_R));
297	                CALL REG_SET(REG_PC, PC + 1);
