 * Integer printing
 * -------------------------------------------------------- */

DCL T_MSG(4) CHAR INIT('PC=');
DCL T_SEP(5) CHAR INIT(' op=');

PRINT_INT: PROC(N INT);
    DCL D INT;
    DCL R INT;
    DCL BUF(8) CHAR;
    DCL POS INT;
    DCL NEG INT;

    IF (N = 0) THEN DO;
        CALL UART_PUTCHAR(48);
        RETURN;
    END;

    NEG = 0;
    IF (N < 0) THEN DO;
        NEG = 1;
        N = 0 - N;
    END;

    POS = 7;
    BUF(POS) = 0;
    DO WHILE (N > 0);
        POS = POS - 1;
        D = N / 10;
        R = N - D * 10;
        BUF(POS) = R + 48;
        N = D;
    END;

    IF (NEG = 1) THEN DO;
        POS = POS - 1;
        BUF(POS) = 45;
    END;

    CALL UART_PUTS(ADDR(BUF) + POS);
END;

