/* vm_io.plsw -- I/O, trace, and atom table operations
 *
 * PRINT_INT, VM_TRACE, atom table store/init/print.
 */
%DEFINE LIBRARY;

%INCLUDE memory;
%INCLUDE vmglob;

/* --------------------------------------------------------
 * Integer printing
 * -------------------------------------------------------- */

DCL T_MSG(4) CHAR INIT('PC=');
DCL T_SEP(5) CHAR INIT(' op=');

PRINT_INT: PROC(N INT);
    DCL D INT;
    DCL R INT;
    DCL BUF(8) CHAR;
    DCL POS INT;
    DCL NEG INT;

    IF (N = 0) THEN DO;
        CALL UART_PUTCHAR(48);
        RETURN;
    END;

    NEG = 0;
    IF (N < 0) THEN DO;
        NEG = 1;
        N = 0 - N;
    END;

    POS = 7;
    BUF(POS) = 0;
    DO WHILE (N > 0);
        POS = POS - 1;
        D = N / 10;
        R = N - D * 10;
        BUF(POS) = R + 48;
        N = D;
    END;

    IF (NEG = 1) THEN DO;
        POS = POS - 1;
        BUF(POS) = 45;
    END;

    CALL UART_PUTS(ADDR(BUF) + POS);
END;

VM_TRACE: PROC(PC INT, OP INT);
    CALL UART_PUTS(ADDR(T_MSG));
    CALL PRINT_INT(PC);
    CALL UART_PUTS(ADDR(T_SEP));
    CALL PRINT_INT(OP);
    CALL UART_PUTCHAR(10);
END;

/* --------------------------------------------------------
 * Atom table
 * -------------------------------------------------------- */

ATOM_STORE: PROC(ID INT, C0 INT, C1 INT, C2 INT, C3 INT,
                  C4 INT, C5 INT, C6 INT);
    DCL BASE INT;
    BASE = ATOM_BASE + ID * ATOM_SLOT_SIZE;
    MEM(BASE)     = C0;
    MEM(BASE + 1) = C1;
    MEM(BASE + 2) = C2;
    MEM(BASE + 3) = C3;
    MEM(BASE + 4) = C4;
    MEM(BASE + 5) = C5;
    MEM(BASE + 6) = C6;
    MEM(BASE + 7) = 0;
END;

ATOM_INIT: PROC;
    /* 0: []       */  CALL ATOM_STORE(0, 91, 93, 0, 0, 0, 0, 0);
